// Set Chrome's actual default page zoom in this disposable BrowserServer profile.
async function setBrowserZoom(browser,factor){
 const cdp=await browser.newBrowserCDPSession();let target;
 try{
  target=await cdp.send('Target.createTarget',{url:'chrome://settings/appearance'});const {sessionId}=await cdp.send('Target.attachToTarget',{targetId:target.targetId,flatten:false});let sequence=0;const pending=new Map();
  cdp.on('Target.receivedMessageFromTarget',e=>{const m=JSON.parse(e.message),p=pending.get(m.id);if(p){clearTimeout(p.timer);pending.delete(m.id);p.resolve(m);}});
  const evaluate=async expression=>{const id=++sequence;const response=new Promise((resolve,reject)=>{const timer=setTimeout(()=>{pending.delete(id);reject(new Error('Chrome zoom command timed out'));},10000);pending.set(id,{resolve,reject,timer});});await cdp.send('Target.sendMessageToTarget',{sessionId,message:JSON.stringify({id,method:'Runtime.evaluate',params:{expression,returnByValue:true,awaitPromise:true}})});const r=await response;assert.equal(r.error,undefined);assert.equal(r.result?.exceptionDetails,undefined);return r.result?.result?.value;};
  assert.equal(await evaluate(`new Promise(resolve=>chrome.settingsPrivate.setDefaultZoom(${factor},()=>resolve(chrome.runtime.lastError?.message??null)))`),null);
  assert.equal(await evaluate('new Promise(resolve=>chrome.settingsPrivate.getDefaultZoom(resolve))'),factor);
 }finally{if(target)await cdp.send('Target.closeTarget',{targetId:target.targetId}).catch(()=>{});await cdp.detach();}
}
